async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  message: {type: 'list_sessions'; limit?: number; before?: Record<string, unknown>}
): Promise<void> {
  if (!sessionStore?.listFor) {
    sendJson(ws, {type: 'session_list', sessions: []});
    return;
  }

  try {
    const summaries = await sessionStore.listFor(session.userId, {limit: message.limit, before: message.before});
    const sessions = summaries.map(summary => ({
      sessionId: summary.sessionId,
      createdAt: summary.createdAt instanceof Date ? summary.createdAt.toISOString() : String(summary.createdAt),
      updatedAt: summary.updatedAt instanceof Date ? summary.updatedAt.toISOString() : String(summary.updatedAt),
      entryCount: summary.entryCount,
    }));
    sendJson(ws, {type: 'session_list', sessions});
  } catch (error) {
    log.error('ws', 'listing sessions failed', {userId: String(session.userId), error: error instanceof Error ? error.message : String(error)});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list sessions');
  }
}

